void mainImage( out vec4 O, in vec2 F )
{
    vec2 u = (F - .5 * iResolution.xy)/iResolution.x;
    vec3 r = normalize(vec3(.5, u.x, u.y)), l = vec3(sin(iTime), cos(iTime), 0), p, c;

    vec4 a = vec4(0,0,0,1);
    float z=-4., s, b, d;
    for (; z < 4.; z+=.1) {
        p = vec3(-9, 0, 0) + (z+9.) * r;
        s = length(p), b = smoothstep(s, s+.5, 4.) * .1;
        d = dot(p/s, l);
        c = vec3(sin(s*2.)*.5+.5, cos(s*2.)*.5+.5, .5) * max(-.05*d, d);

        a.xyz += c * a.a * b;
        a.a *= 1.-b;
    }
    O = pow(a, vec4(.7));
}
